def transform(grid):
    from itertools import permutations

    h, w = len(grid), len(grid[0])
    frame = grid[0][0]

    # The left panel is bounded by full-height columns of the frame color.
    full_cols = [c for c in range(w) if all(grid[r][c] == frame for r in range(h))]
    panel_w = max(full_cols) + 1

    # Full-width frame rows separate the slots.
    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(panel_w))
    ]
    slots = []
    for top, bottom in zip(separators, separators[1:]):
        mask = [
            [grid[r][c] != frame for c in range(1, panel_w - 1)]
            for r in range(top + 1, bottom)
        ]
        slots.append(mask)

    # Extract each colored object's bitmap and bounding box.
    objects = []
    for color in sorted({v for row in grid for v in row if v not in (0, frame)}):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        bitmap = [
            [grid[r][c] == color for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)
        ]
        objects.append((color, bitmap))

    def area(mask):
        return sum(sum(row) for row in mask)

    # Match objects to slots by pixel count, then by bitmap similarity.
    best = None
    for order in permutations(range(len(objects)), len(slots)):
        cost = 0
        for si, oi in enumerate(order):
            slot = slots[si]
            obj = objects[oi][1]
            cost += 100 * abs(area(slot) - area(obj))
            if len(slot) == len(obj) and (not slot or len(slot[0]) == len(obj[0])):
                cost += sum(
                    slot[r][c] != obj[r][c]
                    for r in range(len(slot))
                    for c in range(len(slot[r]))
                )
        if best is None or cost < best[0]:
            best = (cost, order)

    out = [row[:panel_w] for row in grid]
    for si, oi in enumerate(best[1]):
        color = objects[oi][0]
        top, bottom = separators[si], separators[si + 1]
        for r in range(top + 1, bottom):
            for c in range(1, panel_w - 1):
                if grid[r][c] != frame:
                    out[r][c] = color
    return out
